// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2024, "10-11", [{"author":"О. Подлесская","question":"Закончите анекдот: «Во время драки в оркестре выяснилось, что все инструменты — _____».","choices":["смычковые","щипковые","духовые","народные","ударные."],"key":"Д","review":["Анекдот об оркестре","На ударных инструментах звук извлекают ударом. «Смычковые», «щипковые» и «духовые» называют другие способы игры.","В драке любым инструментом могут ударить. Слово «ударные» одновременно подходит к ситуации и остаётся названием группы инструментов."]},{"author":"Л. Фёдорова","question":"Англичане говорят: «Любопытство погубило кошку». А кого вспоминают в близкой по смыслу русской поговорке?","choices":["мышку","собаку","сороку","Ваську","Варвару."],"key":"Д","review":["Поговорка о любопытстве","У английской и русской поговорок общая мысль: чрезмерное любопытство оборачивается неприятностями.","В русском варианте «любопытной Варваре на базаре нос оторвали». Поэтому вспоминают Варвару."]},{"author":"Б. Иомдин","question":"Некоторые из данных ниже слов очень редкие, но все они есть в словарях. Не заглядывая в словарь, скажите, какое слово используется совсем не так, как остальные.","choices":["<em>зимовать</em>","<em>весновать</em>","<em>летовать</em>","<em>осенять</em>","все эти слова используются в одних и тех же контекстах."],"key":"Г","review":["Глаголы о временах года","«Зимовать», «весновать» и «летовать» значат проводить где-то зиму, весну или лето. Они отвечают на вопрос о том, где прошло время года.","«Осенять» — покрывать тенью или внезапно приходить в голову, как мысль. Этот глагол не связан с тем, где проводят осень."]},{"author":"А. Сомин","question":"Что из этого нельзя нанести?","choices":["ущерб","рану","оскорбление","удар","испуг."],"key":"Д","review":["Сочетания с «нанести»","Можно нанести ущерб, рану, оскорбление или удар. Во всех этих выражениях глагол обозначает действие, которое причиняют кому-то.","Об испуге говорят «вызвать испуг», «напугать» или «навести страх». Сочетание «нанести испуг» неупотребительно."]},{"author":"Б. Иомдин","question":"Несколько заметок в «Самарской газете» в 1895 г., подписанные «Дваге», на самом деле написали __________.","choices":["М. Горький и С. Гусев","К. Станиславский и В. Немирович-Данченко","Д. Рукавкин и Н. Второв","М. Дмитриев и В. Воронина","И. Ильф и Е. Петров."],"key":"А","review":["Чей псевдоним «Дваге»","Прочитай подпись как сочетание «два гэ». Это намекает на две одинаковые первые буквы фамилий.","Из перечисленных пар только Горький и Гусев имеют обе фамилии на Г. Они и скрываются под общей подписью."]},{"author":"А. Пиперски","question":"Даны слова: <em>значительный</em>, <em>мерный</em>, <em>сторонний</em>, <em>уважаемый</em>. К каждому из них можно добавить одну и ту же начальную часть, чтобы получилось новое слово. Какое слово обладает тем же свойством?","choices":["<em>детский</em>","<em>лёгкий</em>","<em>красно-белый</em>","<em>людный</em>","<em>абрикосовый</em>."],"key":"Г","review":["Одна начальная часть","Поставь перед каждым словом «много-». Получатся «многозначительный», «многомерный», «многосторонний» и «многоуважаемый».","Тот же способ даёт слово «многолюдный». Остальные предложенные прилагательные так не соединяются с «много-»."]},{"author":"А. Пиперски","question":"__ <em>слонов</em> — __ <em>слонов</em> — __ <em>слонов</em> — __ <em>слонов</em> — __ <em>слонов</em> — __ <em>слона.</em> В этом списке пропущены 6 чисел, причём каждое следующее из них в два раза больше предыдущего. Каким может быть первое число?","choices":["10","9","8","7","6."],"key":"Г","review":["Числа рядом со «слонами»","Форма «слона» нужна после чисел на 2, 3 и 4, кроме оканчивающихся на 12, 13 и 14. Удваивай начальное число и проверяй, когда впервые появится такое окончание.","От 7 получаем 7, 14, 28, 56, 112 и 224. Первые пять чисел требуют «слонов», а 224 требует «слона». При 6, 8 или 9 форма меняется раньше, а от 10 не меняется."]},{"author":"М. Рубинштейн","question":"Четыре из этих фамилий — корейского происхождения, а одна — славянского. Какая?","choices":["<em>Кигай</em>","<em>Огай</em>","<em>Тягай</em>","<em>Хегай</em>","<em>Югай</em>."],"key":"В","review":["Четыре похожие фамилии","Окончание «-гай» встречается в русской передаче ряда корейских фамилий, включая Кигай, Огай, Хегай и Югай.","«Тягай» выделяется славянской основой. Сравни русское и украинское «тягать» в значении «тянуть»."]},{"author":"И. Иткин","question":"У какого из этих языков есть в современном русском общеупотребительное однословное название, выраженное существительным?","choices":["русский","латинский","латышский","литовский","ни у одного нет."],"key":"Б","review":["Два названия языка","Иногда название языка выражают отдельным существительным. Ищи такое слово среди названий языков в списке.","Такое название есть у латинского языка: «латынь». Например, «изучать латынь» значит «изучать латинский язык». Названия «леттский» и «латвийский» для латышского языка выражены прилагательными."],"reviewedEdition":true,"keyNote":"В исходном вопросе «другое название» могло включать «леттский» или «латвийский» для латышского (реестр балтийских языков Ю. Корякова, lingvarium.org/eurasia/IE/balt.shtml, aH2). В интерактивной редакции спрашивается именно о названии-существительном. Ключ Б сохранён."},{"author":"Л. Фёдорова","question":"Как можно правильно перестроить предложение <em>Чай содержит лепестки розы, они придают ему особый аромат</em>?","choices":["<em>Лепестки розы, содерживаемые в чае, придают ему особый аромат.</em>","<em>Лепестки розы, содержимые в чае, придают ему особый аромат</em>.","<em>Лепестки розы, содержанные в чае, придают ему особый аромат</em>.","<em>Лепестки розы, содержащие в чае, придают ему особый аромат</em>.","<em>Лепестки розы, содержащиеся в чае, придают ему особый аромат.</em>"],"key":"Д","review":["Как говорится о чае","Чай содержит лепестки. Чтобы начать с лепестков, нужно сказать, что они содержатся в чае.","От «содержаться» получается «содержащиеся». Форма без «-ся» требовала бы указать, что содержат сами лепестки."]},{"author":"И. Иткин","question":"Какое из этих словосочетаний устроено не так, как остальные?","choices":["<em>японский глагол</em>","<em>японская фраза</em>","<em>японская лексика</em>","<em>японское ругательство</em>","<em>японское заимствование</em>."],"key":"Д","review":["О чём говорит «японский»","Глагол, фраза, лексика и ругательство могут быть японскими по языку, на котором их произносят.","«Японское заимствование» может употребляться в другом языке. Прилагательное указывает на язык, из которого оно пришло."]},{"author":"И. Рубанов","question":"Куда отправляло адресата слово <em>долой</em> в его первоначальном смысле?","choices":["вверх","вниз","влево","вправо","назад."],"key":"Б","review":["Куда отправляют «долой»","Вспомни слова «дол» и «долина», связанные с пониженной местностью. В слове «долой» сохранилось это старое значение.","Изначально «долой» означало «вниз». В современном призыве «долой!» имеется в виду требование убрать кого-то или что-то."]},{"author":"А. Сомин","question":"Какого человека можно было назвать словом <em>мото́ра</em>, которое использовалось в начале XX века в нижегородских диалектах?","choices":["хитрого","расточительного","хромого","гостеприимного","грубого."],"key":"Б","review":["Диалектное название человека","Сравни «мото́ра» со словом «мот». Так называют человека, который без меры тратит средства.","Именно расточительного человека могли назвать «мото́рой». С названием двигателя это слово не связано."]},{"author":"И. Рубанов","question":"От названия какого напитка можно образовать глагол, который обозначает употребление этого напитка?","choices":["воды","кваса","молока","пива","чая."],"key":"Д","review":["Глагол от напитка","Как назвать действие того, кто сидит за чашкой чая? Можно сказать «чаёвничать». В основе глагола слышно название напитка.","Для воды, кваса, молока и пива в обычной речи используют сочетание с «пить». Из списка подходит чай."]},{"author":"О. Подлесская","question":"Какого устойчивого выражения не существует?","choices":["<em>Не так-то было</em>.","<em>То-то и оно</em>.","<em>Вот так так!</em>","<em>Так-то оно так</em>.","<em>Как бы не так</em>."],"key":"А","review":["Устойчивые реплики","«То-то и оно», «Вот так так!», «Так-то оно так» и «Как бы не так» употребляются как готовые реплики.","Говорят «не тут-то было», когда получилось не так, как ожидали. Вариант «Не так-то было» подменяет слово в этом обороте."]},{"author":"А. Остроумова","question":"Как нельзя упасть?","choices":["ничком","навзничь","вдвое","настежь","замертво."],"key":"Г","review":["Как можно упасть","Упасть ничком — лицом вниз, навзничь — на спину. «Замертво» описывает состояние, а величина может упасть вдвое.","«Настежь» говорят про широко открытые двери, окна или ворота. С «упасть» оно не сочетается."]},{"author":"Б. Иомдин","question":"Закончите фразу на хорватском языке: <em>Puškin je izazvao d’Anthèsa na _____</em>.","choices":["piknik","dvoboj","roman","pomoć","smrt."],"key":"Б","review":["Пушкин и Дантес","Названия Пушкина и Дантеса помогают восстановить событие. Пушкин вызвал Дантеса на поединок.","В хорватском «dvoboj» буквально обозначает бой двоих. Поэтому нужно слово «dvoboj»."]},{"author":"И. Иткин","question":"Какую из этих строк А. С. Пушкина можно понять двумя разными способами?","choices":["<em>Что в имени тебе моём?</em>","<em>В глуши что делать в эту пору?</em>","<em>Что так жалобно поют?</em>","<em>Что тревожишь ты меня?</em>","Все эти строки однозначны."],"key":"В","review":["Два вопроса со словом «что»","В строке «Что так жалобно поют?» слово «что» можно связать с содержанием пения: какую песню поют?","Оно может также значить «почему»: почему поют так жалобно? Две грамматические роли создают два смысла."]},{"author":"Б. Иомдин","question":"Какое слово отличается от других по составу?","choices":["<em>московский</em>","<em>литовский</em>","<em>мордовский</em>","<em>днепровский</em>","все слова устроены одинаково."],"key":"Г","review":["Где находится «в»","В словах «московский», «литовский» и «мордовский» звук В принадлежит основе от «Москва», «Литва» и «Мордва». Добавляется «-ск-».","В слове «Днепр» В нет. В «днепровский» оно входит в часть, добавленную к основе. Поэтому слово устроено по-другому."]},{"author":"О. Подлесская","question":"<em>С него _____.</em> Найдите пару глаголов, каждый из которых может закончить эту фразу с одинаковым смыслом.","choices":["<em>хватит</em> — <em>хватится</em>","<em>сходит</em> — <em>сходится</em>","<em>требует</em> — <em>требуется</em>","<em>станет</em> — <em>станется</em>","берёт — берётся."],"key":"Г","review":["«С него …»","Сравни «с него хватит» и «он хватится»: в первом случае чего-то достаточно, во втором он заметит пропажу. Так же проверяй остальные пары.","«С него станет» и «с него станется» можно сказать в одном значении: человек вполне способен так поступить."]},{"author":"О. Подлесская","question":"Поэт Д. Авалиани придумал фразы, подчиняющиеся определённому правилу. Какой пример не принадлежит Д. Авалиани?","choices":["<em>Государство</em> — <em>сговор у стад.</em>","<em>Низменное неизменно.</em>","<em>Симметрия</em> — <em>имя смерти.</em>","<em>Художества дух освежат.</em>","<em>Страданье: не радость.</em>"],"key":"Д","review":["Буквы переставили местами","Сравни буквы по обе стороны тире или пробела. В «государство — сговор у стад» и «симметрия — имя смерти» вторые части используют те же буквы. Это верно и для «низменное неизменно» и «художества дух освежат».","В «страданье» и «не радость» количество и набор букв отличаются. Например, в «страданье» нет О. Этот пример нарушает правило."]},{"author":"А. Нужненко","question":"В испанском языке к мужскому роду обычно относятся существительные с окончанием -o, к женскому — существительные с окончанием -a. Найдите в приведённом ниже списке существительное женского рода.","choices":["vino","foto","efecto","documento","candidato."],"key":"Б","review":["Род в испанском языке","В испанском «foto» — сокращение от «fotografía». При сокращении выпала часть слова с обычным окончанием женского рода.","Род сохраняется: говорят «la foto». Остальные слова на «-o» из списка относятся к мужскому роду."]},{"author":"И. Рубанов","question":"Вот список слов: <em>благолепие</em>, <em>великолепный</em>, <em>лепет</em>, <em>лепта</em>, <em>нелепый</em>. Сколько среди них исторически однокоренных?","choices":["два","три","четыре","пять","однокоренных слов в этом списке нет."],"key":"Б","review":["Древний корень «леп-»","В «благолепии» и «великолепном» сохранился старый корень со значением красоты, пригожести. «Нелепый» в старом смысле — неподходящий или некрасивый.","«Лепет» обозначает неясную речь, «лепта» заимствована из греческого. Исторически однокоренных слов три."]},{"author":"Е. Муравенко","question":"Даны названия лиц женского пола по национальности: англичанка, немка, француженка, шведка, китаянка, японка. Образуйте соответствующие названия лиц мужского пола. Сколько разных типов соотношения названий для лиц мужского и женского пола здесь представлено?","choices":["шесть","пять","четыре","три","два."],"key":"Б","review":["Названия мужчин и женщин","Запиши шесть пар: англичанка — англичанин, немка — немец, француженка — француз, шведка — швед, китаянка — китаец, японка — японец.","Одинаково устроены «немка — немец» и «японка — японец». Остальные пары различаются: замена на «-ин», форма с чередованием Ж и З, убирание «-к-» и замена части «-янк-» на «-ец». Всего пять типов."]},{"author":"А. Сомин","question":"В какое из этих слов можно вместо двух разных гласных букв подставить две одинаковые и получить устаревшее слово с тем же значением?","choices":["<em>эпос</em>","<em>роман</em>","<em>автор</em>","<em>сонет</em>","<em>поэт</em>."],"key":"Д","review":["Устаревшее название поэта","Нужно изменить две разные гласные одного слова на одну и ту же. В «поэт» возьми буквы О и Э.","Замени их на И. Получится «пиит», устаревшее слово со значением «поэт»."]},{"author":"Б. Иомдин","question":"<em>— Да освободись ты как-нибудь, — просил Лёша. Новый ответсекретарь был великодушен: — Гуляй на здоровье — заменим, завтра отрубишь</em> (П. Сиркес). В одном слове этого отрывка мы пропустили одну букву. Какую?","choices":["<em>а</em>","<em>к</em>","<em>с</em>","<em>т</em>","<em>у</em>."],"key":"Г","review":["Пропавшая согласная","Из контекста ясно, что завтра Лёша будет работать вместо того, кто его подменил. Прочитай последний глагол в этом значении.","Нужен глагол «оттрубить» — отработать положенное время. В форме «оттрубишь» есть две Т подряд. Одна из них пропущена."]},{"author":"А. Бегункова","question":"Какое слово дважды пропущено в четверостишии из стихотворения Андрея Белого «Утро»?\n<em>Над _____ мглистой в выси синей\nЧистый-чистый серебристый иней.\nНад _____, — как извивы лилий,\nКак изливы лебединых крылий.</em>","choices":["<em>долиной</em>","<em>поляной</em>","<em>дорогой</em>","<em>рекою</em>","<em>землёю</em>."],"key":"А","review":["Иней в четверостишии","Первые две строки рассказывают о дымке и инее над протяжённым пространством. Читаем отрывок как описание утреннего пейзажа.","У Андрея Белого и в первой, и в третьей строке стоит «над долиной». Это название места восстанавливает обе строки."]},{"author":"Е. Бикмаев и О. Подлесская","question":"В каждой из пяти поговорок дважды пропущено одно и то же слово. В каком случае эти слова относятся к одному и тому же объекту действительности?","choices":["<em>От _____ _____ не ищут</em>.","<em>Без _____ _____ женили</em>.","<em>_____ _____ видит издалека</em>.","<em>_____ _____ моет</em>.","<em>_____ _____ волк</em>."],"key":"Б","review":["Одно слово, один объект","В «От добра добра не ищут» речь о благе, которое уже есть, и другом, которого можно искать. «Рыбак рыбака видит», «Рука руку моет», «Человек человеку волк» говорят о двух людях или двух руках.","В выражении «Без меня меня женили» оба «меня» обозначают одного говорящего. Поэтому подходит эта поговорка."]},{"author":"А. Сомин","question":"Название какого из этих музыкальных инструментов исторически образовано от славянского глагола, который значит ‘производить звук (определённого типа)’?","choices":["арфа","волынка","лютня","гусли","гармонь."],"key":"Г","review":["Название инструмента и звук","Ищи инструмент, название которого связано со старым глаголом «гудеть». Струны могут звучать, издавая протяжный гул.","В названии «гусли» сохранился корень, родственный «гудеть». Другие названия из списка имеют иное происхождение."]},{"author":"П. Долгополов","question":"Словенский и верхнелужицкий — славянские языки, родственные русскому. На словенский русские слова <em>голый</em> и <em>хмель</em> переводятся как gol и hmelj, а на верхнелужицкий — как hoły и chmjel. А что означает слово hlada на словенском и верхнелужицком? (В верхнелужицком ł читается как w в английском, а l — как русское <em>ль</em>.)","choices":["слов. ‘холода’, в.-луж. ‘смотрит’","слов. ‘голода’, в.-луж. ‘смотрит’","слов. ‘гладит’, в.-луж. ‘холода’","слов. ‘смотрит’, в.-луж. ‘холода’","слов. ‘холода’, в.-луж. ‘гладит’."],"key":"А","review":["Одно написание в двух языках","Словенское «gol» показывает соответствие русского Г и словенского g, а «hmelj» — русского Х и словенского h. Поэтому словенское «hlada» связано с «хладом», или «холодом».","В верхнелужицком «hoły» начальное h соответствует русскому Г. Значит, «hlada» родственно основе «гляд-» и означает «смотрит». Подходит первый вариант."]}], {"year":2024,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2024-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
